 if len(q)<8 or q.clv.std()==0: return pd.Series(np.nan,index=g.index)
 return pd.Series(q.body-q.clv.cov(q.body)/q.clv.var()*q.clv, index=q.index)
a['f']=a.groupby('date',group_keys=False).apply(resid).reindex(a.index)
